/**
 * Apply the ApplyFidEntriesCommand to a program.
 *
 */
public class FidAnalyzer : AbstractAnalyzer {
	private static readonly string NAME = "Function ID";
	private static readonly string DESCRIPTION = "Finds known functions by hashing.";

	private FidService service;

	// Options
	private static readonly string OPTION_NAME_CREATE_BOOKMARKS = "Create Analysis Bookmarks";
	private static readonly string OPTION_DESCRIPTION_CREATE_BOOKMARKS =
		"If checked, an analysis bookmark will be created for each function which was matched " +
			"against one or more known library functions.";

	private static readonly string IGNORE_FILTERS_OPTION_NAME = "Ignore Database Filters";
	private static readonly string IGNORE_FILTERS_OPTION_DESCRIPTION = "If checked, the " +
		"analyzer will try to apply labels from any FID file even if the targeted compilers " +
		"and source languages don't match the program.  Only the FID file's language ID must match";

	public static readonly string APPLY_ALL_FID_LABELS_OPTION_NAME = "Always Apply FID Labels";
	private static readonly string APPLY_ALL_FID_LABELS_OPTION_DESCRIPTION = "Enable this option to " +
		"always apply FID labels at functions regardless of existing labels at that function." +
		" When enabled, FID labels will always be added." +
		" When disabled, FID labels will not be applied at functions where " +
		" there already exists a label with type IMPORTED or USER_DEFINED.";

	// Default Option Values
	private static readonly bool APPLY_ALL_FID_LABELS_DEFAULT = false;
	private static readonly bool OPTION_DEFAULT_CREATE_BOOKMARKS_ENABLED = true;
	private static readonly bool IGNORE_FILTERS_DEFAULT = false;

	// Option Variables
	private bool alwaysApplyFidLabels = APPLY_ALL_FID_LABELS_DEFAULT;
	private bool createBookmarksEnabled = OPTION_DEFAULT_CREATE_BOOKMARKS_ENABLED;
	private bool ignoreFilters = IGNORE_FILTERS_DEFAULT;

	private static readonly string SCORE_THRESHOLD_OPTION_NAME = "Instruction Count Threshold";

	private static readonly string SCORE_THRESHOLD_OPTION_DESCRIPTION =
		"The minimum score that a potential match must meet to be labeled by the analyzer. " +
			"Score corresponds roughly to the number of instructions in the function.";
	private float scoreThreshold;

	private static readonly string MULTIMATCH_THRESHOLD_OPTION_NAME = "Multiple Match Threshold";
	private static readonly string MULTIMATCH_THRESHOLD_OPTION_DESCRIPTION =
		"If there are multiple conflicting matches for a function, its score must exceed " +
			"this secondary threshold in order to be labeled by the analyzer";
	private float multiScoreThreshold;

//==================================================================================================
// Old Option Names - Should stick around for multiple major versions after 10.2
//==================================================================================================

	private static readonly string SCORE_THRESHOLD_OPTION_NAME_OLD = "Instruction count threshold";
	private static readonly string MULTIMATCH_THRESHOLD_OPTION_NAME_OLD = "Multiple match threshold";
	private static readonly string APPLY_ALL_FID_LABELS_OPTION_NAME_OLD = "Always apply FID labels";

	private AnalysisOptionsUpdater optionsUpdater = new AnalysisOptionsUpdater();

//==================================================================================================
// End Old Option Names
//==================================================================================================

	public FidAnalyzer() {
		/*
		 * FID is listed as a byte analyzer because we don't want to run it all the time.  It
		 * wants to look at as much of the surrounding code (call tree really) as it can, which
		 * means it's expensive.  It can't be running every time a new function is created.
		 *
		 * On the other hand, it's important to identify some types of common functions by their
		 * name...exception handlers for instance, or other non-exiting functions.  So FID should
		 * run as soon as possible after most of the function bodies are discovered.  (FID relies
		 * on proper function bodies existing).
		 */
		super(NAME, DESCRIPTION, AnalyzerType.BYTE_ANALYZER);
		service = new FidService();
		setSupportsOneTimeAnalysis();
		setPriority(AnalysisPriority.FUNCTION_ID_ANALYSIS.before());
		scoreThreshold = service.getDefaultScoreThreshold();
		multiScoreThreshold = service.getDefaultMultiNameThreshold();

		optionsUpdater.registerReplacement(SCORE_THRESHOLD_OPTION_NAME,
			SCORE_THRESHOLD_OPTION_NAME_OLD);
		optionsUpdater.registerReplacement(MULTIMATCH_THRESHOLD_OPTION_NAME,
			MULTIMATCH_THRESHOLD_OPTION_NAME_OLD);
		optionsUpdater.registerReplacement(APPLY_ALL_FID_LABELS_OPTION_NAME,
			APPLY_ALL_FID_LABELS_OPTION_NAME_OLD);
	}

	/* @Override */
	public bool getDefaultEnablement(Program program) {
		// Loading Fid db files can be slow.  For now, signal that we can analyze and check later.
		return true;
		//return service.canProcess(program.getLanguage());
	}

	/* @Override */
	public bool canAnalyze(Program program) {
		// Loading Fid db files can be slow.  For now, signal that we can analyze and check later.
		return true;
		//return service.canProcess(program.getLanguage());
	}

	/* @Override */
	public bool added(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log)
    {

		if (!service.canProcess(new FidProgramID(program, ignoreFilters))) {
			// This can now happen, since we no longer check in canAnalyze()
			Msg.debug(this, "No FID Libraries apply for language " + program.getLanguageID());
			return false;
		}

		if (!isFullExecutable(program, set)) {
			return true;
		}

		ApplyFidEntriesCommand cmd;
		cmd = new ApplyFidEntriesCommand(set, scoreThreshold, multiScoreThreshold,
			alwaysApplyFidLabels, createBookmarksEnabled, ignoreFilters);
		cmd.applyTo(program, monitor);

		// Name Change can change the nature of a function from a system
		// library. Probably a better way to do this.
		AutoAnalysisManager.getAnalysisManager(program)
				.functionModifierChanged(cmd.getFIDLocations());
		return true;
	}

	/**
	 * Check if set contains the full executable or loaded/initialized memory areas.
	 * 
	 * @param program program to check
	 * @param set set to check
	 * @return true if all program executable or load/initialized memory is in set
	 */
	private bool isFullExecutable(Program program, AddressSetView set) {
		// if has an execute set, then set to FID, must contain the execute set
		AddressSetView executeSet = program.getMemory().getExecuteSet();
		if (!executeSet.isEmpty()) {
			return set.contains(executeSet);
		}

		// if there are no execute blocks, then use loaded/initialized for program blocks
		AddressSetView loadSet = program.getMemory().getLoadedAndInitializedAddressSet();
		return set.contains(loadSet);
	}

	/* @Override */
	public void registerOptions(Options options, Program program) {
		options.registerOption(SCORE_THRESHOLD_OPTION_NAME, service.getDefaultScoreThreshold(),
			null, SCORE_THRESHOLD_OPTION_DESCRIPTION);
		options.registerOption(MULTIMATCH_THRESHOLD_OPTION_NAME,
			service.getDefaultMultiNameThreshold(), null, MULTIMATCH_THRESHOLD_OPTION_DESCRIPTION);
		options.registerOption(APPLY_ALL_FID_LABELS_OPTION_NAME, APPLY_ALL_FID_LABELS_DEFAULT, null,
			APPLY_ALL_FID_LABELS_OPTION_DESCRIPTION);
		options.registerOption(OPTION_NAME_CREATE_BOOKMARKS, createBookmarksEnabled, null,
			OPTION_DESCRIPTION_CREATE_BOOKMARKS);
		options.registerOption(IGNORE_FILTERS_OPTION_NAME, ignoreFilters, null,
			IGNORE_FILTERS_OPTION_DESCRIPTION);
	}

	/* @Override */
	public AnalysisOptionsUpdater getOptionsUpdater() {
		return optionsUpdater;
	}

	/* @Override */
	public void optionsChanged(Options options, Program program) {
		scoreThreshold =
			options.getFloat(SCORE_THRESHOLD_OPTION_NAME, service.getDefaultScoreThreshold());
		multiScoreThreshold = options.getFloat(MULTIMATCH_THRESHOLD_OPTION_NAME,
			service.getDefaultMultiNameThreshold());
		alwaysApplyFidLabels =
			options.getBoolean(APPLY_ALL_FID_LABELS_OPTION_NAME, APPLY_ALL_FID_LABELS_DEFAULT);
		createBookmarksEnabled =
			options.getBoolean(OPTION_NAME_CREATE_BOOKMARKS, createBookmarksEnabled);
		ignoreFilters =
			options.getBoolean(IGNORE_FILTERS_OPTION_NAME, ignoreFilters);
	}

}
